public class LinearSearch {
    public static int search(int[] arr, int target) {
         for (int i = 0; i < arr.length; i++) {
             if (arr[i] == target) return i;
         }
         return -1;
    }
}

Implement binary search on a sorted array.
Challenge: Track the number of recursive calls made.
public class BinarySearch {
     public static int search(int[] arr, int target) {
          int low = 0, high = arr.length - 1;
     while (low <= high) {
               int mid = (low + high) / 2;
               if (arr[mid] == target) return mid;
               else if (arr[mid] < target) low = mid + 1;
               else high = mid - 1;
          }
     return -1;
     }
}

public class ExponentialSearch {
    public static int search(int[] arr, int target) {
        if (arr[0] == target) return 0;
        int i = 1;
        while (i < arr.length && arr[i] <= target) i *= 2;
        return binarySearch(arr, i / 2, Math.min(i, arr.length - 1), target);
    }
    private static int binarySearch(int[] arr, int low, int high, int target) {
        while (low <= high) {
            int mid = (low + high) / 2;
            if (arr[mid] == target) return mid;
            else if (arr[mid] < target) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }
}

public class InterpolationSearch {
   public static int search(int[] arr, int target) {
     int low = 0, high = arr.length - 1;
     while (low <= high && target >= arr[low] &&
            target <= arr[high]) {
                    int pos = low + ((target - arr[low]) *
                    (high - low)) / arr[high] - arr[low]);
            if (arr[pos] == target) return pos;
            else if (arr[pos] < target) low = pos + 1;
     else high = pos - 1;        }
   return -1;    }}

